class Solution {
public:
    vector<int> intersection(vector<int>& nums1, vector<int>& nums2) {
        bool present[1001] = {false};
        bool added[1001] = {false};
        for (int x : nums1) {
            present[x] = true;
        }
        vector<int> result;
        for (int x : nums2) {
            if (present[x] && !added[x]) {
                result.push_back(x);
                added[x] = true;
            }
        }
        return result;
    }
};
